                    ..state
                };
                (state_prime, None)
            } else {
                let pod = make_pod(v_replica_set);
                let req = APIRequest::CreateRequest(CreateRequest {
                    namespace: namespace,
                    obj: pod.marshal(),
                });
                let state_prime = VReplicaSetReconcileState {
                    reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
